namespace SoulExe.Services;

/// <summary>Vanilla, responsive local client shared stylistically with SoulExe Mobile.</summary>
internal static class MobileStyleWebClient
{
    internal const string Content = """
<!doctype html>
<html lang="ru"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#090b14"><title>SoulExe Mobile</title>
<style>
:root{color-scheme:dark;--bg:#090b14;--surface:#121625;--surface2:#1a2032;--line:#303952;--text:#f4f6ff;--muted:#9aa6c7;--accent:#6d3df5;--accent2:#426bff;--accentsoft:#2d2850;--action:#f4b860;--thought:#8eccff;--danger:#ff7190;--success:#34d399}*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;background:var(--bg);color:var(--text);font:14px/1.42 Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;overflow:hidden}button,input,textarea,select{font:inherit}button{border:0;cursor:pointer;color:var(--text)}#app{height:100dvh;background:var(--bg)}.screen{min-height:100%;display:flex;flex-direction:column;max-width:720px;margin:auto;background:linear-gradient(180deg,#0e1220 0,#090b14 23%)}.content{min-height:0;flex:1;overflow:auto;-webkit-overflow-scrolling:touch;padding:10px 12px calc(82px + env(safe-area-inset-bottom))}.thread{padding:0;overflow:hidden}.bottom{height:65px;padding:7px 16px calc(7px + env(safe-area-inset-bottom));display:flex;justify-content:space-around;gap:10px;background:rgba(18,22,37,.97);border-top:1px solid var(--line)}.tab{min-width:68px;background:transparent;color:var(--muted);font-size:10px;font-weight:750;display:grid;justify-items:center;gap:2px;padding:3px}.tab .tabico{font-size:21px;line-height:22px}.tab.active{color:#a995ff}.topbar{min-height:64px;padding:calc(9px + env(safe-area-inset-top)) 14px 9px;display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--line);background:rgba(18,22,37,.97);position:sticky;top:0;z-index:3}.back,.miniicon{border-radius:50%;width:38px;height:38px;display:grid;place-items:center;background:#202840;color:#c9d3ff;font-size:20px}.topcopy{min-width:0;flex:1}.topcopy b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.topcopy small{display:block;color:var(--muted);font-size:11px;margin-top:1px}.brandtop{display:flex;align-items:center;gap:9px;margin:4px 2px 13px}.brandmark{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:linear-gradient(145deg,#7f64f7,#315fd4);font-size:18px;box-shadow:0 8px 20px #4f54aa42}.brandtop b{font-size:16px}.brandtop span{display:block;font-size:10px;color:var(--muted);margin-top:1px}.threadlist{display:grid;gap:2px}.threadrow{width:100%;display:flex;align-items:center;gap:11px;padding:11px 8px;border-radius:14px;background:transparent;text-align:left}.threadrow:active{background:#1a2032}.threadcopy{min-width:0;flex:1}.threadname{display:flex;align-items:center;gap:6px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.threadpreview{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px}.threadmeta{align-self:flex-start;color:var(--muted);font-size:10px;margin-top:2px}.avatar{width:46px;height:46px;min-width:46px;border-radius:50%;display:grid;place-items:center;overflow:hidden;background:linear-gradient(145deg,#687fff,#3048ca);color:white;font-weight:800;font-size:16px}.avatar.small{width:32px;height:32px;min-width:32px;font-size:12px;margin-left:-10px;border:2px solid var(--bg)}.avatar.small:first-child{margin-left:0}.avatar img{width:100%;height:100%;object-fit:cover}.avatarpair{display:flex;align-items:center;min-width:54px}.tag{font-size:9px;line-height:1;padding:4px 6px;border-radius:9px;background:#2a3150;color:#bdc9ff}.tag.running{background:#153c36;color:#86f2d0}.empty{padding:56px 20px;text-align:center;color:var(--muted)}.empty .big{font-size:28px;display:block;margin-bottom:9px}.fab{position:fixed;z-index:5;right:max(22px,calc((100vw - 720px)/2 + 18px));bottom:calc(83px + env(safe-area-inset-bottom));width:56px;height:56px;border-radius:50%;font-size:29px;line-height:1;background:linear-gradient(135deg,var(--accent),var(--accent2));box-shadow:0 10px 24px #352c8f88}.day{display:flex;align-items:center;gap:9px;justify-content:center;color:var(--muted);font-size:10px;font-weight:750;margin:16px 0 8px}.day:before,.day:after{content:"";height:1px;flex:1;background:#273049}.messages{padding:3px 12px 8px;min-height:calc(100dvh - 188px)}.message{display:flex;margin:8px 0}.message.right{justify-content:flex-end}.message.center{justify-content:center}.bubblewrap{max-width:84%}.message.center .bubblewrap{max-width:92%}.author{font-size:10px;color:var(--muted);margin:0 4px 3px}.right .author{text-align:right}.bubble{border:1px solid var(--line);border-radius:17px;border-bottom-left-radius:5px;background:#1f2633;padding:9px 11px;white-space:pre-wrap;overflow-wrap:anywhere}.right .bubble{border-color:#8ea6ff;background:linear-gradient(135deg,#5278ff,#345df5);border-bottom-left-radius:17px;border-bottom-right-radius:5px}.center .bubble{border-radius:12px;background:#23283a;color:#bfc8e3;text-align:center;font-size:12px}.action{color:var(--action);font-style:italic}.thought{color:var(--thought)}.speech{color:#ffe099}.msgtime{font-size:9px;color:#b9c5ee;margin:4px 2px 0;text-align:right}.composer{display:flex;align-items:flex-end;gap:7px;padding:8px 12px calc(8px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:rgba(12,15,26,.98);position:sticky;bottom:0}.composeinput{min-width:0;flex:1;min-height:44px;max-height:112px;resize:none;padding:11px 13px;color:var(--text);background:#182035;border:1px solid #35405e;border-radius:22px;outline:none;line-height:20px}.round{width:42px;height:42px;min-width:42px;border-radius:50%;background:#26304b;color:#dbe5ff;font-size:18px;display:grid;place-items:center}.round.primary{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff}.round.warn{background:#3a3140;color:#ffcb89}.card{padding:13px;margin:10px 0;border:1px solid var(--line);border-radius:16px;background:var(--surface)}.cardtitle{font-size:12px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin:0 0 10px}.split{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field{margin:10px 0}.field label{display:block;font-size:10px;font-weight:800;letter-spacing:.06em;color:var(--muted);margin:0 0 5px}.field input,.field textarea,.field select{width:100%;color:var(--text);background:#1b2135;border:1px solid #39435f;border-radius:11px;padding:10px;outline:none}.field textarea{resize:vertical;min-height:72px}.primarybtn,.secondarybtn{width:100%;border-radius:12px;padding:12px;background:linear-gradient(135deg,var(--accent),var(--accent2));font-weight:800;margin-top:8px}.secondarybtn{background:#222941;color:#dce3ff}.profilehero{padding:26px 18px 18px;text-align:center;background:linear-gradient(180deg,#171d32,#111624);border-bottom:1px solid var(--line)}.profilehero .avatar{width:82px;height:82px;margin:0 auto 10px;font-size:30px}.profilehero h2{margin:0;font-size:20px}.profilehero p{margin:4px auto 0;color:var(--muted);max-width:380px}.info{padding:10px 14px;border-bottom:1px solid #252c43}.info label{display:block;color:var(--muted);font-size:10px;font-weight:800;margin-bottom:4px}.info p{margin:0;white-space:pre-wrap}.login{justify-content:center;padding:26px;min-height:100%}.loginbrand{text-align:center;margin-bottom:30px}.loginbrand .brandmark{width:70px;height:70px;margin:0 auto 13px;font-size:31px}.loginbrand h1{font-size:22px;margin:0}.loginbrand p{color:var(--muted);max-width:310px;margin:8px auto}.login .card{max-width:400px;width:100%;margin:0 auto}.notice{font-size:12px;color:var(--muted);padding:9px 2px}.hidden{display:none!important}.sheetback{position:fixed;inset:0;z-index:20;background:#0009;display:flex;align-items:flex-end;justify-content:center;padding:12px}.sheet{width:min(720px,100%);max-height:90dvh;overflow:auto;background:#121625;border:1px solid #39435f;border-radius:20px 20px 14px 14px;padding:17px}.sheethead{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.sheethead h2{margin:0;font-size:17px}.close{background:transparent;color:var(--muted);font-size:26px;padding:0 4px}.choice{width:100%;display:flex;gap:12px;align-items:center;padding:12px 4px;border-bottom:1px solid #273049;background:transparent;text-align:left}.choice .choiceico{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#29264a;font-size:20px}.choice p{margin:2px 0 0;color:var(--muted);font-size:12px}.switchrow{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid #273049}.switchrow input{accent-color:var(--accent);width:20px;height:20px}@media(min-width:721px){.content{border-left:1px solid #20263b;border-right:1px solid #20263b}.fab{right:calc(50% - 338px)}}@media(max-width:390px){.split{grid-template-columns:1fr}.bubblewrap{max-width:91%}}
</style></head><body><div id="app"><main class="screen login"><section class="loginbrand"><div class="brandmark">◌</div><h1>SoulExe Mobile</h1><p>Подключитесь к SoulExe на компьютере, чтобы продолжить диалоги с персонажами.</p></section><section class="card"><div class="field"><label>ЛОГИН</label><input id="login" autocomplete="username"></div><div class="field"><label>ПАРОЛЬ</label><input id="password" type="password" autocomplete="current-password"></div><button class="primarybtn" id="signin">Войти</button><p class="notice">Загрузка веб-клиента… Если это сообщение не сменится экраном входа, обновите страницу.</p></section></main></div><script>
const root=document.querySelector('#app');
const defaultAppearance={stripActionMarkers:false,stripThoughtMarkers:false,stripSpeechMarkers:false,actionColor:'#f4b860',thoughtColor:'#8eccff',speechColor:'#ffe099'};
const readStoredObject=(key,fallback)=>{try{const raw=localStorage.getItem(key);if(!raw)return fallback;const value=JSON.parse(raw);return value&&typeof value==='object'&&!Array.isArray(value)?value:fallback}catch{return fallback}};
const readSession=()=>{try{return sessionStorage.getItem('soulexe-mobile-session')||''}catch{return''}};
const state={session:readSession(),tab:'chats',characters:[],threads:[],active:null,poll:0,busy:false,appearance:{...defaultAppearance,...readStoredObject('soulexe-web-appearance',{})}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const by=id=>document.getElementById(id);const now=()=>new Date();const time=v=>{try{return new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit'}).format(new Date(v))}catch{return''}};
const api=async(path,opt={})=>{const isGet=!opt.method||opt.method.toUpperCase()==='GET';const url=isGet?path+(path.includes('?')?'&':'?')+'_='+Date.now():path;const res=await fetch(url,{...opt,cache:'no-store',headers:{'X-SoulExe-Session':state.session,...(opt.headers||{})}});let data={};try{data=await res.json()}catch{}if(!res.ok){const e=Error(data.error||'Не удалось выполнить действие.');e.status=res.status;throw e}return data};
const participantCharacter=p=>state.characters.find(c=>c.id===(p?.characterId||p?.id))||{id:p?.characterId||p?.id,name:p?.displayName||'Персонаж',avatarUrl:p?.avatarUrl};
function chatView(c){const p=c.participants.find(x=>x.kind==='Character'),character=participantCharacter(p);return{kind:'chat',id:c.id,character,chat:{id:c.id,name:c.name,updatedAt:c.updatedAt},messages:c.messages.map(m=>({role:m.authorParticipantId===p?.id?'bot':m.kind==='system'?'system':'user',author:m.author,content:m.content,createdAt:m.createdAt}))}}
function sceneView(c){const people=c.participants.filter(x=>x.kind==='Character').sort((a,b)=>a.sortOrder-b.sortOrder).map(participantCharacter);return{id:c.id,name:c.name,status:c.turnState?.status||'paused',updatedAt:c.updatedAt,nextTurnAt:c.turnState?.nextTurnAt,characterA:people[0],characterB:people[1],scenario:c.context?.scenario,location:c.context?.location,timeContext:c.context?.timeContext,mood:c.context?.mood,goal:c.context?.goal,relationshipContext:c.context?.relationshipContext,turnMode:c.turnState?.mode,delaySeconds:c.turnState?.delaySeconds||0,enforceSceneContract:c.turnState?.enforceContract,advanceSceneAndAvoidRepetition:c.turnState?.advanceAndAvoidRepetition,messages:c.messages.map(m=>({kind:m.kind==='director'?'director':'dialogue',speakerId:m.authorParticipantId,author:m.author,content:m.content,createdAt:m.createdAt}))}}
const avatar=p=>`<div class="avatar">${p?.avatarUrl?`<img src="${esc(p.avatarUrl)}?s=${encodeURIComponent(state.session)}" alt="">`:esc((p?.name||'?')[0].toUpperCase())}</div>`;
const miniAvatar=p=>`<div class="avatar small">${p?.avatarUrl?`<img src="${esc(p.avatarUrl)}?s=${encodeURIComponent(state.session)}" alt="">`:esc((p?.name||'?')[0].toUpperCase())}</div>`;
function clean(v){let t=String(v??'');if(state.appearance.stripThoughtMarkers)t=t.replace(/<\/?think\b[^>]*>/gi,'');if(state.appearance.stripActionMarkers)t=t.replace(/\*([^*\n]+)\*/g,'$1');if(state.appearance.stripSpeechMarkers)t=t.replace(/«([^»\n]+)»|"([^"\n]+)"/g,'$1$2');return t.replace(/\s+/g,' ').trim()}
function rich(v){let text=esc(clean(v));text=text.replace(/&lt;think&gt;([\s\S]*?)&lt;\/think&gt;/gi,'<span class="thought">$1</span>');if(!state.appearance.stripActionMarkers)text=text.replace(/\*([^*\n]+)\*/g,'<span class="action">*$1*</span>');if(!state.appearance.stripSpeechMarkers)text=text.replace(/(«[^»\n]+»|&quot;[^&\n]+&quot;)/g,'<span class="speech">$1</span>');return text}
function day(v){const d=new Date(v),n=new Date(),y=new Date();y.setDate(n.getDate()-1);const key=x=>`${x.getFullYear()}-${x.getMonth()}-${x.getDate()}`;if(key(d)===key(n))return'Сегодня';if(key(d)===key(y))return'Вчера';return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:d.getFullYear()===n.getFullYear()?undefined:'numeric'}).format(d)}
function dates(messages,render){let prev='';return messages.map(m=>{const k=new Date(m.createdAt).toDateString(),divider=k!==prev?`<div class="day">${day(m.createdAt)}</div>`:'';prev=k;return divider+render(m)}).join('')}
function saveAppearance(){try{localStorage.setItem('soulexe-web-appearance',JSON.stringify(state.appearance))}catch{}applyAppearance()}
function applyAppearance(){document.documentElement.style.setProperty('--action',state.appearance.actionColor);document.documentElement.style.setProperty('--thought',state.appearance.thoughtColor);document.documentElement.style.setProperty('--speech',state.appearance.speechColor)}
function tabbar(){return `<nav class="bottom"><button class="tab ${state.tab==='chats'?'active':''}" data-tab="chats"><span class="tabico">◌</span>Чаты</button><button class="tab ${state.tab==='characters'?'active':''}" data-tab="characters"><span class="tabico">♙</span>Персонажи</button><button class="tab ${state.tab==='settings'?'active':''}" data-tab="settings"><span class="tabico">⚙</span>Ещё</button></nav>`}
function shell(content,thread=false){clearTimeout(state.poll);root.innerHTML=`<main class="screen"><section class="content ${thread?'thread':''}">${content}</section>${thread?'':tabbar()}</main>`;root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.active=null;render()})}
async function load(){[state.characters,state.threads]=await Promise.all([api('/api/characters'),api('/api/conversations?take=1')]);state.threads=state.threads.map(c=>{const preview=c.messages.at(-1)?.content||c.context?.scenario||'Нет сообщений';if(c.mode==='group'){const scene=sceneView(c);return{kind:'scene',id:c.id,scene,updatedAt:c.updatedAt,preview}}const view=chatView(c);return{...view,updatedAt:c.updatedAt,preview}}).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));render()}
function render(){if(!state.session)return login();if(state.active?.kind==='chat')return chatThread(state.active);if(state.active?.kind==='scene')return sceneThread(state.active);if(state.tab==='characters')return characters();if(state.tab==='settings')return settings();threads()}
function threads(){const items=state.threads.map(t=>{const isScene=t.kind==='scene',name=isScene?t.scene.name:(t.character.name||t.chat.name),meta=isScene?`<span class="tag ${t.scene.status==='running'?'running':''}">${t.scene.status==='running'?'Идёт':'Пауза'}</span>`:time(t.updatedAt);const face=isScene?`<div class="avatarpair">${miniAvatar(t.scene.characterA)}${miniAvatar(t.scene.characterB)}</div>`:avatar(t.character);return`<button class="threadrow" data-open="${t.kind}:${t.id}">${face}<span class="threadcopy"><span class="threadname">${esc(name)} ${isScene?'<span class="tag">Сцена</span>':''}</span><span class="threadpreview">${esc(clean(t.preview||''))}</span></span><span class="threadmeta">${meta}</span></button>`}).join('');shell(`<div class="brandtop"><div class="brandmark">◌</div><div><b>SoulExe</b><span>Ваши персонажи — рядом</span></div></div><div class="threadlist">${items||'<div class="empty"><span class="big">◌</span>Пока нет диалогов.<br>Создайте чат или сцену.</div>'}</div><button class="fab" id="new">＋</button>`);root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open));by('new').onclick=newSheet}
async function open(key){const [kind,id]=key.split(':'),conversation=await api('/api/conversations/'+id+'?take=60');state.active=kind==='chat'?chatView(conversation):{kind:'scene',id,scene:sceneView(conversation)};render()}
function topbar(title,subtitle,info){return`<header class="topbar"><button class="back" id="back">‹</button><div class="topcopy"><b>${esc(title)}</b><small>${esc(subtitle||'')}</small></div><button class="miniicon" id="info">ⓘ</button></header>`}
function messageMarkup(messages,scene){return dates(messages,m=>{let align='left',author=m.author||'';if(scene){if(m.kind==='director'||!m.speakerId)align='center';else if(m.speakerId===scene.characterB?.id)align='right'}else if(m.role==='user')align='right';return`<div class="message ${align}"><div class="bubblewrap"><div class="author">${esc(author)}</div><div class="bubble">${rich(m.content)}</div><div class="msgtime">${time(m.createdAt)}</div></div></div>`})}
function autoGrow(el){el.style.height='auto';el.style.height=Math.min(112,Math.max(44,el.scrollHeight))+'px'}
function composer(scene){return`<div class="composer">${scene?`<button class="round warn" id="pause">${scene.status==='running'?'Ⅱ':'▶'}</button>`:''}<textarea id="compose" class="composeinput" rows="1" placeholder="${scene?'Режиссёрское событие…':'Напишите сообщение…'}"></textarea>${scene?'<button class="round" id="director">✦</button><button class="round primary" id="next">↑</button>':'<button class="round primary" id="send">↑</button>'}</div>`}
function chatThread(a){const subtitle=a.messages?.length?`Был(а) в ${time(a.messages.at(-1)?.createdAt)}`:'Нет сообщений';shell(`${topbar(a.character.name,subtitle)}<div class="messages" id="messages">${messageMarkup(a.messages||[],null)}</div>${composer()}`,true);bindThreadBase(()=>characterProfile(a.character));const input=by('compose');input.oninput=()=>autoGrow(input);by('send').onclick=()=>sendChat(a);scrollEnd();}
async function sendChat(a){const input=by('compose'),text=input.value.trim();if(!text||state.busy)return;state.busy=true;input.value='';autoGrow(input);a.messages.push({role:'user',author:'Вы',content:text,createdAt:new Date().toISOString()});a.messages.push({role:'system',author:'',content:'Персонаж печатает…',createdAt:new Date().toISOString(),typing:true});render();try{await api('/api/conversations/'+a.id+'/actions?async=1',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'send',text})});pollChat(a,text)}catch(e){alert(e.message);state.busy=false}}
async function pollChat(a,sent){for(let i=0;i<180;i++){await new Promise(r=>setTimeout(r,1000));if(state.active!==a)return;const fresh=chatView(await api('/api/conversations/'+a.id+'?take=60')),messages=fresh.messages;const n=messages.findIndex(m=>m.role==='user'&&m.content===sent);if(n>=0&&messages.slice(n+1).some(m=>m.role==='bot')){a.messages=messages;state.busy=false;render();return}}state.busy=false;render()}
function sceneThread(a){const s=a.scene,people=`${s.characterA?.name||'?'} · ${s.characterB?.name||'?'}`,status=s.status==='running'?'Идёт · таймер '+s.delaySeconds+' с':'Пауза';shell(`${topbar(s.name,people+' · '+status)}<div class="messages" id="messages">${messageMarkup(s.messages||[],s)}</div>${composer(s)}`,true);bindThreadBase(()=>sceneProfile(s));const input=by('compose');input.oninput=()=>autoGrow(input);by('pause').onclick=()=>sceneAction(s,s.status==='running'?'pause':'start');by('next').onclick=()=>sceneAction(s,'next');by('director').onclick=()=>director(s);scrollEnd();watchScene(s)}
async function sceneAction(s,action){try{const next=await api('/api/conversations/'+s.id+'/actions?async=1',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});if(next?.id)state.active.scene=sceneView(next);else s.status=action==='pause'?'paused':'running';render()}catch(e){alert(e.message)}}
async function director(s){const input=by('compose'),text=input.value.trim();if(!text)return;try{const next=await api('/api/conversations/'+s.id+'/actions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'director',text})});const active=state.active;if(active?.kind==='scene'){active.scene=sceneView(next);render()}}catch(e){alert(e.message)}}
function watchScene(s){if(s.status!=='running')return;state.poll=setTimeout(async()=>{if(state.active?.kind!=='scene'||state.active.id!==s.id)return;try{state.active.scene=sceneView(await api('/api/conversations/'+s.id+'?take=60'));render()}catch{watchScene(s)}},1100)}
function bindThreadBase(infoFn){by('back').onclick=()=>{state.active=null;render()};by('info').onclick=infoFn}
function scrollEnd(){requestAnimationFrame(()=>{const m=by('messages');if(m)m.parentElement.scrollTop=m.parentElement.scrollHeight})}
function characters(){const list=state.characters.map(c=>`<button class="threadrow" data-char="${c.id}">${avatar(c)}<span class="threadcopy"><span class="threadname">${esc(c.name)}</span><span class="threadpreview">${esc(c.title||c.description||'Персонаж SoulExe')}</span></span></button>`).join('');shell(`<div class="brandtop"><div class="brandmark">♙</div><div><b>Персонажи</b><span>Библиотека ваших образов</span></div></div><div class="threadlist">${list||'<div class="empty">Библиотека пока пуста.</div>'}</div><button class="fab" id="newchar">＋</button>`);root.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>characterProfile(state.characters.find(c=>c.id===b.dataset.char)));by('newchar').onclick=characterCreate}
function characterProfile(c){state.active={kind:'profile'};shell(`${topbar(c.name,c.title||'Профиль персонажа')}<section class="profilehero">${avatar(c)}<h2>${esc(c.name)}</h2><p>${esc(c.title||'Персонаж SoulExe')}</p><button class="secondarybtn" id="edit">Редактировать</button></section><article class="info"><label>ОПИСАНИЕ</label><p>${esc(c.description||'Не заполнено')}</p></article><article class="info"><label>ЛИЧНОСТЬ</label><p>${esc(c.personality||'Не заполнено')}</p></article><article class="info"><label>СЦЕНАРИЙ</label><p>${esc(c.scenario||'Не заполнено')}</p></article>`,true);by('back').onclick=()=>{state.active=null;render()};by('info').onclick=()=>{};by('edit').onclick=()=>characterEdit(c)}
function characterEdit(c){shell(`${topbar('Редактирование',c.name)}<form id="charform" class="card"><div class="field"><label>ИМЯ</label><input id="cn" value="${esc(c.name)}"></div><div class="field"><label>РОЛЬ</label><input id="ct" value="${esc(c.title||'')}"></div><div class="field"><label>ОПИСАНИЕ</label><textarea id="cd">${esc(c.description||'')}</textarea></div><div class="field"><label>ЛИЧНОСТЬ</label><textarea id="cp">${esc(c.personality||'')}</textarea></div><div class="field"><label>СЦЕНАРИЙ</label><textarea id="cs">${esc(c.scenario||'')}</textarea></div><button class="primarybtn">Сохранить</button></form>`,true);by('back').onclick=()=>characterProfile(c);by('info').onclick=()=>{};by('charform').onsubmit=async e=>{e.preventDefault();try{const n=await api('/api/characters/'+c.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:by('cn').value,title:by('ct').value,description:by('cd').value,personality:by('cp').value,scenario:by('cs').value})});state.characters=state.characters.map(x=>x.id===n.id?n:x);characterProfile(n)}catch(er){alert(er.message)}}}
function sceneProfile(s){shell(`${topbar(s.name,'Информация о сцене')}<section class="profilehero"><div class="avatarpair" style="justify-content:center;margin:auto">${miniAvatar(s.characterA)}${miniAvatar(s.characterB)}</div><h2>${esc(s.name)}</h2><p>${esc(s.characterA?.name||'?')} и ${esc(s.characterB?.name||'?')}</p><button class="secondarybtn" id="edit">Редактировать параметры</button></section>${sceneInfo('Сценарий',s.scenario)}${sceneInfo('Место',s.location)}${sceneInfo('Время',s.timeContext)}${sceneInfo('Настроение',s.mood)}${sceneInfo('Цель',s.goal)}${sceneInfo('Отношения',s.relationshipContext)}${sceneInfo('Режим ходов',s.turnMode)}${sceneInfo('Интервал',s.delaySeconds+' секунд')}`,true);by('back').onclick=()=>{state.active={kind:'scene',id:s.id,scene:s};render()};by('info').onclick=()=>{};by('edit').onclick=()=>sceneForm(s)}
const sceneInfo=(label,value)=>`<article class="info"><label>${esc(label)}</label><p>${esc(value||'Не задано')}</p></article>`;
function settings(){shell(`<div class="brandtop"><div class="brandmark">⚙</div><div><b>Ещё</b><span>Оформление и доступ</span></div></div><section class="card"><p class="cardtitle">Оформление сообщений</p>${switchRow('actions','Скрывать звёздочки действий',state.appearance.stripActionMarkers)}${switchRow('thoughts','Скрывать теги мыслей',state.appearance.stripThoughtMarkers)}${switchRow('speech','Скрывать кавычки речи',state.appearance.stripSpeechMarkers)}<div class="split"><div class="field"><label>ДЕЙСТВИЯ</label><input id="actionColor" type="color" value="${state.appearance.actionColor}"></div><div class="field"><label>МЫСЛИ</label><input id="thoughtColor" type="color" value="${state.appearance.thoughtColor}"></div></div><div class="field"><label>РЕЧЬ</label><input id="speechColor" type="color" value="${state.appearance.speechColor}"></div></section><section class="card"><p class="cardtitle">Локальная сессия</p><p class="notice">Веб-клиент работает только пока SoulExe запущен на вашем компьютере.</p><button class="secondarybtn" id="logout">Выйти</button></section>`);['actions','thoughts','speech'].forEach(k=>by(k).onchange=e=>{state.appearance[{actions:'stripActionMarkers',thoughts:'stripThoughtMarkers',speech:'stripSpeechMarkers'}[k]]=e.target.checked;saveAppearance()});[['actionColor','actionColor'],['thoughtColor','thoughtColor'],['speechColor','speechColor']].forEach(([id,key])=>by(id).oninput=e=>{state.appearance[key]=e.target.value;saveAppearance()});by('logout').onclick=()=>{state.session='';sessionStorage.removeItem('soulexe-mobile-session');login()}}
const switchRow=(id,text,checked)=>`<label class="switchrow"><span>${text}</span><input id="${id}" type="checkbox" ${checked?'checked':''}></label>`;
function newSheet(){sheet(`<div class="sheethead"><h2>Создать</h2><button class="close" data-close>×</button></div><button class="choice" id="makechat"><span class="choiceico">◌</span><span><b>Новый чат</b><p>Диалог с одним персонажем</p></span></button><button class="choice" id="makescene"><span class="choiceico">✦</span><span><b>Новая сцена</b><p>Два участника и параметры сюжета</p></span></button>`);by('makechat').onclick=chatForm;by('makescene').onclick=()=>sceneForm()}
function chatForm(){sheet(`<div class="sheethead"><h2>Новый разговор</h2><button class="close" data-close>×</button></div><form id="newchat"><div class="field"><label>ПЕРСОНАЖ</label><select id="cc">${state.characters.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>НАЗВАНИЕ</label><input id="cname" value="Новый разговор"></div><button class="primarybtn">Создать</button></form>`);by('newchat').onsubmit=async e=>{e.preventDefault();try{const n=await api('/api/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({characterIds:[by('cc').value],name:by('cname').value})});closeSheet();await load();open('chat:'+n.id)}catch(er){alert(er.message)}}}
function sceneForm(existing){const s=existing||{},ch=state.characters;sheet(`<div class="sheethead"><h2>${existing?'Параметры разговора':'Новый групповой разговор'}</h2><button class="close" data-close>×</button></div><form id="sceneform"><div class="split"><div class="field"><label>ПЕРВЫЙ УЧАСТНИК</label><select id="sa">${ch.map(c=>`<option value="${c.id}" ${c.id===s.characterA?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>ВТОРОЙ УЧАСТНИК</label><select id="sb">${ch.map(c=>`<option value="${c.id}" ${c.id===s.characterB?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>${sceneFields(s)}<button class="primarybtn">${existing?'Сохранить':'Создать'}</button></form>`);by('sceneform').onsubmit=async e=>{e.preventDefault();const body={characterIds:[by('sa').value,by('sb').value],name:by('sn').value,scenario:by('ss').value,location:by('sl').value,timeContext:by('st').value,mood:by('sm').value,goal:by('sg').value,relationshipContext:by('sr').value,turnMode:by('turn').value,delaySeconds:+by('delay').value,enforceContract:by('contract').checked,advanceAndAvoidRepetition:by('advance').checked};if(body.characterIds[0]===body.characterIds[1])return alert('Выберите двух разных участников.');try{const n=await api(existing?'/api/conversations/'+existing.id:'/api/conversations',{method:existing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});closeSheet();await load();open('scene:'+n.id)}catch(er){alert(er.message)}}}
function sceneFields(s){const f=(id,l,v,area=false)=>`<div class="field"><label>${l}</label>${area?`<textarea id="${id}">${esc(v||'')}</textarea>`:`<input id="${id}" value="${esc(v||'')}">`}</div>`;return f('sn','НАЗВАНИЕ',s.name)+f('ss','СЦЕНАРИЙ',s.scenario,true)+f('sl','МЕСТО',s.location)+f('st','ВРЕМЯ',s.timeContext)+f('sm','НАСТРОЕНИЕ',s.mood)+f('sg','ЦЕЛЬ',s.goal)+f('sr','ОТНОШЕНИЯ',s.relationshipContext)+`<div class="split"><div class="field"><label>РЕЖИМ</label><select id="turn"><option value="alternate">По очереди</option><option value="manual">Вручную</option></select></div><div class="field"><label>ИНТЕРВАЛ, СЕК.</label><input id="delay" type="number" min="1" value="${s.delaySeconds||45}"></div></div><label class="switchrow"><span>Соблюдать рамки сцены</span><input id="contract" type="checkbox" ${s.enforceSceneContract?'checked':''}></label><label class="switchrow"><span>Развивать сцену</span><input id="advance" type="checkbox" ${s.advanceSceneAndAvoidRepetition?'checked':''}></label>`}
function characterCreate(){sheet(`<div class="sheethead"><h2>Новый персонаж</h2><button class="close" data-close>×</button></div><form id="newchar"><div class="field"><label>ИМЯ</label><input id="ncn" placeholder="Имя персонажа"></div><div class="field"><label>КРАТКОЕ ОПИСАНИЕ</label><textarea id="ncd" placeholder="Кто это и какой характер?"></textarea></div><button class="primarybtn">Создать вручную</button><button type="button" class="secondarybtn" id="genchar">Сгенерировать через ИИ</button></form>`);by('newchar').onsubmit=async e=>{e.preventDefault();try{await api('/api/characters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:by('ncn').value,description:by('ncd').value})});closeSheet();await load()}catch(er){alert(er.message)}};by('genchar').onclick=async()=>{try{await api('/api/characters/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idea:by('ncd').value||by('ncn').value})});closeSheet();await load()}catch(er){alert(er.message)}}}
function sheet(content){document.querySelectorAll('.sheetback').forEach(x=>x.remove());document.body.insertAdjacentHTML('beforeend',`<div class="sheetback"><section class="sheet">${content}</section></div>`);document.querySelector('[data-close]').onclick=closeSheet;document.querySelector('.sheetback').onclick=e=>{if(e.target.classList.contains('sheetback'))closeSheet()}}
function closeSheet(){document.querySelectorAll('.sheetback').forEach(x=>x.remove())}
function login(){root.innerHTML=`<main class="screen login"><section class="loginbrand"><div class="brandmark">◌</div><h1>SoulExe Mobile</h1><p>Подключитесь к SoulExe на компьютере, чтобы продолжить диалоги с персонажами.</p></section><section class="card"><div class="field"><label>ЛОГИН</label><input id="login" autocomplete="username"></div><div class="field"><label>ПАРОЛЬ</label><input id="password" type="password" autocomplete="current-password"></div><button class="primarybtn" id="signin">Войти</button><p class="notice">Данные задаются в разделе «Мобильный доступ» приложения SoulExe.</p></section></main>`;by('signin').onclick=async()=>{try{const result=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:by('login').value,password:by('password').value})});state.session=result.session;try{sessionStorage.setItem('soulexe-mobile-session',state.session)}catch{}await load()}catch{alert('Неверный логин или пароль.')}}}
function showBootError(error){const message=esc(error?.message||String(error)||'Неизвестная ошибка запуска.');root.innerHTML=`<main class="screen login"><section class="loginbrand"><div class="brandmark">!</div><h1>Ошибка запуска веб-клиента</h1><p>Страница SoulExe не смогла завершить загрузку.</p></section><section class="card"><p class="notice">${message}</p><button class="primarybtn" id="retry">Повторить загрузку</button></section></main>`;const retry=by('retry');if(retry)retry.onclick=()=>location.reload()}
async function boot(){try{applyAppearance();if(!state.session)return login();await load()}catch(e){if(e?.status===401){state.session='';try{sessionStorage.removeItem('soulexe-mobile-session')}catch{}login()}else showBootError(e)}}
Promise.resolve().then(boot).catch(showBootError);
</script></body></html>
""";
}
